preConditionHook:
// NEW EXTREME FREQUENCY (Brian's notes ON-62, #62), a trend-strength filter.
// Of the last windowBars bars (current included), count those whose high is
// the high of the extremeBars bars ENDING at that bar (EL
// high[i] >= Highest(high, extremeBars)[i], inclusive '=' convention as in
// HighestHighBreakout); long when the count is at least fraction x
// windowBars. Short counts extremeBars-bar lows. Highest at a loop offset is
// open-coded Extremes in both twins (seeded at bar i, strict comparison).
hiCnt = 0;
loCnt = 0;
for (int ii = 0; ii <= (int)windowBars - 1; ++ii) {
    hh = high[ii];
    ll = low[ii];
    for (int jj = 1; jj <= (int)extremeBars - 1; ++jj) {
        if (el_gt(high[ii + jj], hh)) hh = high[ii + jj];
        if (el_lt(low[ii + jj], ll)) ll = low[ii + jj];
    }
    if (el_ge(high[ii], hh)) hiCnt = hiCnt + 1;
    if (el_le(low[ii], ll)) loCnt = loCnt + 1;
}
